//! Read-only parity against the Python-generated geometry/STL corpus.
//!
//! Every assertion here consumes `backend/fixtures/corpus/v1`; the fixtures
//! are never written or regenerated by this crate.

mod common;

use std::fs;

use common::{
    as_array, as_f64, as_object, as_str, as_u64, digest_floats, digest_u32, fixture_path,
    load_json, repo_root, sha256_hex,
};
use kala_geometry::{
    Bounds, DEFAULT_BOX_EDGE_SUBDIVISIONS, DEFAULT_BOX_SIZE_MM, DEFAULT_CYLINDER_HEIGHT_MM,
    DEFAULT_CYLINDER_HEIGHT_SEGMENTS, DEFAULT_CYLINDER_RADIAL_SEGMENTS, DEFAULT_CYLINDER_RADIUS_MM,
    DEFAULT_SPHERE_RADIUS_MM, DEFAULT_SPHERE_RINGS, DEFAULT_SPHERE_SECTORS,
    MAX_BOX_EDGE_SUBDIVISIONS, MAX_CYLINDER_HEIGHT_SEGMENTS, MAX_CYLINDER_RADIAL_SEGMENTS,
    MAX_MESH_TRIANGLES, MAX_MESH_VERTICES, MAX_SPHERE_RINGS, MAX_SPHERE_SECTORS, Mesh,
    PrimitiveParameters, build_primitive, compute_bounds, signed_volume,
    welded_edges_by_position_pairs, write_binary_stl,
};
use serde_json::Value;

const FIXTURE: &str = "geometry_stl.json";

fn build_case(case: &Value) -> Mesh {
    let kind = as_str(&case["kind"]);
    let parameters = PrimitiveParameters::from_json_value(&case["parameters"])
        .unwrap_or_else(|error| panic!("case {} parameters: {error}", as_str(&case["id"])));
    build_primitive(kind, &parameters)
        .unwrap_or_else(|error| panic!("case {} build: {error}", as_str(&case["id"])))
}

fn sample_matches(actual: &[f64], expected: &Value, label: &str) {
    let expected = as_array(expected);
    assert_eq!(actual.len(), expected.len(), "{label} sample length");
    for (index, (actual, expected)) in actual.iter().zip(expected).enumerate() {
        assert_eq!(
            actual.to_bits(),
            as_f64(expected).to_bits(),
            "{label} sample element {index}"
        );
    }
}

#[test]
fn fixture_defaults_and_maxima_match_crate_constants() {
    let fixture = load_json(FIXTURE);
    let defaults = as_object(&fixture["defaults"]);
    assert_eq!(
        as_f64(&defaults["box_size_mm"]).to_bits(),
        DEFAULT_BOX_SIZE_MM.to_bits()
    );
    assert_eq!(
        as_u64(&defaults["box_edge_subdivisions"]) as u32,
        DEFAULT_BOX_EDGE_SUBDIVISIONS
    );
    assert_eq!(
        as_f64(&defaults["cylinder_radius_mm"]).to_bits(),
        DEFAULT_CYLINDER_RADIUS_MM.to_bits()
    );
    assert_eq!(
        as_f64(&defaults["cylinder_height_mm"]).to_bits(),
        DEFAULT_CYLINDER_HEIGHT_MM.to_bits()
    );
    assert_eq!(
        as_u64(&defaults["cylinder_radial_segments"]) as u32,
        DEFAULT_CYLINDER_RADIAL_SEGMENTS
    );
    assert_eq!(
        as_u64(&defaults["cylinder_height_segments"]) as u32,
        DEFAULT_CYLINDER_HEIGHT_SEGMENTS
    );
    assert_eq!(
        as_f64(&defaults["sphere_radius_mm"]).to_bits(),
        DEFAULT_SPHERE_RADIUS_MM.to_bits()
    );
    assert_eq!(
        as_u64(&defaults["sphere_rings"]) as u32,
        DEFAULT_SPHERE_RINGS
    );
    assert_eq!(
        as_u64(&defaults["sphere_sectors"]) as u32,
        DEFAULT_SPHERE_SECTORS
    );

    let maxima = as_object(&fixture["maxima"]);
    assert_eq!(
        as_u64(&maxima["box_edge_subdivisions"]) as u32,
        MAX_BOX_EDGE_SUBDIVISIONS
    );
    assert_eq!(
        as_u64(&maxima["cylinder_radial_segments"]) as u32,
        MAX_CYLINDER_RADIAL_SEGMENTS
    );
    assert_eq!(
        as_u64(&maxima["cylinder_height_segments"]) as u32,
        MAX_CYLINDER_HEIGHT_SEGMENTS
    );
    assert_eq!(as_u64(&maxima["sphere_rings"]) as u32, MAX_SPHERE_RINGS);
    assert_eq!(as_u64(&maxima["sphere_sectors"]) as u32, MAX_SPHERE_SECTORS);
    assert_eq!(as_u64(&maxima["mesh_vertices"]) as usize, MAX_MESH_VERTICES);
    assert_eq!(
        as_u64(&maxima["mesh_triangles"]) as usize,
        MAX_MESH_TRIANGLES
    );

    let layout = as_object(&fixture["stl_layout"]);
    assert_eq!(as_u64(&layout["header_bytes"]) as usize, 80);
    assert_eq!(as_u64(&layout["triangle_record_bytes"]) as usize, 50);
    assert_eq!(
        as_str(&layout["triangle_record_format"]),
        kala_geometry::STL_BINARY_FORMAT
    );
    assert_eq!(as_u64(&layout["attribute_byte_count"]), 0);
    assert_eq!(
        as_str(&layout["header_fill"]).as_bytes(),
        kala_geometry::STL_HEADER_FILL
    );
}

#[test]
fn all_six_fixture_meshes_match_arrays_bounds_volume_and_watertightness() {
    let fixture = load_json(FIXTURE);
    let cases = as_array(&fixture["meshes"]);
    assert_eq!(cases.len(), 6, "fixture must contain all six meshes");

    for case in cases {
        let id = as_str(&case["id"]);
        let mesh = build_case(case);

        assert_eq!(
            mesh.vertex_count() as u64,
            as_u64(&case["vertex_count"]),
            "{id} vertex count"
        );
        assert_eq!(
            mesh.triangle_count() as u64,
            as_u64(&case["triangle_count"]),
            "{id} triangle count"
        );

        let positions = as_object(&case["positions"]);
        assert_eq!(
            mesh.positions().len() as u64,
            as_u64(&positions["length"]),
            "{id} positions length"
        );
        assert_eq!(
            digest_floats(mesh.positions()),
            as_str(&positions["sha256_of_compact_json"]),
            "{id} positions compact-JSON digest"
        );
        sample_matches(
            &mesh.positions()[..6],
            &positions["first"],
            &format!("{id} positions first"),
        );
        sample_matches(
            &mesh.positions()[mesh.positions().len() - 6..],
            &positions["last"],
            &format!("{id} positions last"),
        );

        let normals = as_object(&case["normals"]);
        assert_eq!(
            mesh.normals().len() as u64,
            as_u64(&normals["length"]),
            "{id} normals length"
        );
        assert_eq!(
            digest_floats(mesh.normals()),
            as_str(&normals["sha256_of_compact_json"]),
            "{id} normals compact-JSON digest"
        );
        sample_matches(
            &mesh.normals()[..6],
            &normals["first"],
            &format!("{id} normals first"),
        );
        sample_matches(
            &mesh.normals()[mesh.normals().len() - 6..],
            &normals["last"],
            &format!("{id} normals last"),
        );

        let indices = as_object(&case["indices"]);
        assert_eq!(
            mesh.indices().len() as u64,
            as_u64(&indices["length"]),
            "{id} indices length"
        );
        assert_eq!(
            digest_u32(mesh.indices()),
            as_str(&indices["sha256_of_compact_json"]),
            "{id} indices compact-JSON digest"
        );
        let expected_first: Vec<u32> = as_array(&indices["first"])
            .iter()
            .map(|value| as_u64(value) as u32)
            .collect();
        let expected_last: Vec<u32> = as_array(&indices["last"])
            .iter()
            .map(|value| as_u64(value) as u32)
            .collect();
        assert_eq!(
            &mesh.indices()[..6],
            expected_first.as_slice(),
            "{id} indices first"
        );
        assert_eq!(
            &mesh.indices()[mesh.indices().len() - 6..],
            expected_last.as_slice(),
            "{id} indices last"
        );

        let bounds = compute_bounds(mesh.positions()).expect("mesh has complete positions");
        let expected_bounds = &case["bounds"];
        let expected_min = [
            as_f64(&expected_bounds["min"][0]),
            as_f64(&expected_bounds["min"][1]),
            as_f64(&expected_bounds["min"][2]),
        ];
        let expected_max = [
            as_f64(&expected_bounds["max"][0]),
            as_f64(&expected_bounds["max"][1]),
            as_f64(&expected_bounds["max"][2]),
        ];
        assert_eq!(
            bounds,
            Bounds {
                min: expected_min,
                max: expected_max,
            },
            "{id} bounds"
        );

        let volume = signed_volume(&mesh);
        let expected_volume = as_f64(&case["signed_volume"]);
        assert!(
            (volume - expected_volume).abs() <= 1e-9 * expected_volume.abs().max(1.0),
            "{id} signed volume {volume} differs from oracle {expected_volume}"
        );
        assert!(volume > 0.0, "{id} signed volume must be positive");

        let edges = welded_edges_by_position_pairs(&mesh);
        let expected_edges = as_object(&case["welded_edge_symmetric_counts"]);
        assert_eq!(
            edges.len() as u64,
            as_u64(&expected_edges["distinct_edges"]),
            "{id} distinct welded edges"
        );
        assert!(
            edges.values().all(|uses| *uses == 2),
            "{id} must be watertight: every position-keyed edge used twice"
        );
        assert!(
            as_object(&case["welded_edge_symmetric_counts"])["all_edges_used_twice"]
                .as_bool()
                .unwrap(),
            "{id} fixture watertightness flag"
        );

        let stl = write_binary_stl(&mesh);
        let stl_record = as_object(&case["stl"]);
        assert_eq!(
            stl.len() as u64,
            as_u64(&stl_record["length"]),
            "{id} STL length"
        );
        assert_eq!(
            sha256_hex(&stl),
            as_str(&stl_record["sha256"]),
            "{id} STL SHA-256"
        );
        let header_ascii = String::from_utf8_lossy(&stl[..80]).trim_end().to_owned();
        assert_eq!(
            header_ascii,
            as_str(&stl_record["header_ascii"]),
            "{id} STL header text"
        );
        let header_count = u32::from_le_bytes(stl[80..84].try_into().expect("STL count field"));
        assert_eq!(
            header_count as u64,
            as_u64(&stl_record["triangle_count_from_header"]),
            "{id} STL header triangle count"
        );
        assert_eq!(
            header_count as usize,
            mesh.triangle_count(),
            "{id} STL count field"
        );
    }
}

#[test]
fn stored_default_stls_are_byte_identical() {
    let fixture = load_json(FIXTURE);
    let cases = as_array(&fixture["meshes"]);
    let mut checked = 0;
    for case in cases {
        let stl_record = as_object(&case["stl"]);
        let Some(stored_file) = stl_record["stored_file"].as_str() else {
            continue;
        };
        let mesh = build_case(case);
        let actual = write_binary_stl(&mesh);
        let expected = fs::read(fixture_path(&format!("stl/{stored_file}")))
            .unwrap_or_else(|error| panic!("read {stored_file}: {error}"));
        assert_eq!(
            actual,
            expected,
            "{} default STL bytes must match the checked-in artifact",
            as_str(&case["id"])
        );
        assert_eq!(
            sha256_hex(&actual),
            as_str(&stl_record["stored_file_sha256"]),
            "{} stored file digest",
            as_str(&case["id"])
        );
        checked += 1;
    }
    assert_eq!(checked, 3, "the three default STLs are checked in");
}

#[test]
fn fixture_manifest_matches_files_on_disk() {
    let manifest = load_json("manifest.json");
    let root = repo_root();
    assert!(
        root.join("src/kala_agent/studio/geometry/meshes.py")
            .is_file(),
        "source oracle must exist at the repository root"
    );
    let geometry_bytes = fs::read(fixture_path(FIXTURE)).unwrap();
    let entry = as_array(&manifest["files"])
        .iter()
        .find(|entry| entry["path"] == FIXTURE)
        .expect("manifest indexes geometry_stl.json");
    assert_eq!(
        as_u64(&entry["size_bytes"]),
        geometry_bytes.len() as u64,
        "fixture byte length"
    );
    assert_eq!(
        as_str(&entry["sha256"]),
        sha256_hex(&geometry_bytes),
        "fixture digest"
    );
}
